if (pose_estimation_axis === "x") {
    if (orientationZ >= -0.3 && orientationZ <= 0.3) {
        current_position.position[pose_estimation_axis] += difference_distance;
    } else if (orientationZ >= 0.9 && orientationZ <= 1) {
        current_position.position[pose_estimation_axis] -= difference_distance;
    }
} else if (pose_estimation_axis === "y") {
    if (orientationZ >= 0.4 && orientationZ <= 0.8) {
        current_position.position[pose_estimation_axis] += difference_distance;
    } else if (orientationZ <= -0.4 && orientationZ >= -0.8) {
        current_position.position[pose_estimation_axis] -= difference_distance;
    }
}

// สร้าง payload ส่งออก
msg.payload = {
    "currentPos_before": current_position_pre_edit,
    "arRead": arRead_value,
    "default": default_distance,
    "axis": pose_estimation_axis,
    "difference": difference_distance,
    "orientationZ": orientationZ,
    "position_update": current_position
};


return msg;

